#include <WiFi.h>
#include <esp_now.h>

uint8_t receiverMac[] = {0x24, 0x6F, 0x28, 0xAA, 0xBB, 0xCC};
const char message[] = "sensor=24";

void setup() {
  Serial.begin(115200);
  if (!WiFi.mode(WIFI_STA)) {
    Serial.println("Wi-Fi station mode failed");
    return;
  }
  if (esp_now_init() != ESP_OK) {
    Serial.println("ESP-NOW initialization failed");
    return;
  }

  esp_now_peer_info_t peer{};
  memcpy(peer.peer_addr, receiverMac, 6);
  peer.channel = 0;
  peer.encrypt = false;  // Demo only; configure encryption for private data.
  if (esp_now_add_peer(&peer) != ESP_OK) return;

  esp_err_t result = esp_now_send(
      receiverMac, reinterpret_cast<const uint8_t*>(message), sizeof(message));
  Serial.println(result == ESP_OK ? "queued" : "send error");
}

void loop() {}
